type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // shape must be [R, C]
    assert!(
        shape.len() == 2,
        "The shape vector must have exactly two elements."
    );
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    let n = a.len();
    assert!(n > 0, "Input array must be non-empty.");
    assert!(
        n == r || n == c,
        "The length of `a` must equal either R or C."
    );

    let mut result: Matrix<i8> = Vec::with_capacity(r);

    if n == r {
        // Treat `a` as a column vector: broadcast each a[i] across columns
        for i in 0..r {
            result.push(vec![a[i]; c]);
        }
    } else {
        // Treat `a` as a row vector: broadcast the entire row for each of the r rows
        for _ in 0..r {
            result.push(a.clone());
        }
    }

    result
}

